import { computed, defineComponent, h, ref, type PropType } from 'vue';
import { getToggleState, getToggleStyleKeys } from '../lib/core';
import type { ToggleVariant, ToggleSize } from '../lib/core';
import styles from './toggle.module.scss';

export const Toggle = defineComponent({
	name: 'Toggle',
	props: {
		modelValue: { type: Boolean, default: undefined },
		defaultValue: { type: Boolean, default: false },
		variant: {
			type: String as PropType<ToggleVariant>,
			default: 'default',
		},
		size: {
			type: String as PropType<ToggleSize>,
			default: 'default',
		},
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, attrs, slots }) {
		const internalValue = ref(props.defaultValue);
		const isPressed = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));
		const state = computed(() => getToggleState(isPressed.value));
		const styleKeys = computed(() => getToggleStyleKeys(props.variant, props.size));
		const classes = computed(() => [styles[styleKeys.value.base], styles[styleKeys.value.variant], styles[styleKeys.value.size]]);

		function handleClick() {
			const next = !isPressed.value;
			if (props.modelValue === undefined) {
				internalValue.value = next;
			}
			emit('update:modelValue', next);
			emit('change', next);
		}

		return () =>
			h(
				'button',
				{
					...attrs,
					type: 'button',
					'aria-pressed': isPressed.value ? 'true' : 'false',
					'data-state': state.value,
					'data-variant': props.variant,
					'data-size': props.size,
					disabled: props.disabled,
					class: [...classes.value, attrs.class],
					onClick: handleClick,
				},
				slots.default?.(),
			);
	},
});

export default Toggle;

@use '../../../styles/variables/colors' as *;

.toggle {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--tile-toggle-gap, #{$spacing-2});
	white-space: nowrap;
	border-radius: var(--tile-toggle-radius, #{$radius});
	border: 1px solid transparent;
	font-size: var(--tile-toggle-font-size, #{$text-sm});
	line-height: var(--tile-toggle-line-height, inherit);
	font-weight: $font-medium;
	transition:
		color $transition-fast,
		background-color $transition-fast,
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&:focus-visible {
		border-color: var(--tile-toggle-focus-border, #{$ring});
		box-shadow: var(--tile-toggle-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
		cursor: not-allowed;
	}

	svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
	}

	// 状态
	&[data-state='on'] {
		background-color: var(--tile-toggle-selected-background, #{$accent});
		color: var(--tile-toggle-selected-color, #{$accent-foreground});
	}

	&[data-state='off'] {
		background-color: transparent;
		color: $foreground;

		&:hover:not(:disabled) {
			background-color: var(--tile-toggle-hover-background, #{$muted});
			color: var(--tile-toggle-hover-color, #{$muted-foreground});
		}
	}

	// 样式变体
	&.variantDefault {
		background-color: transparent;

		&[data-state='on'] {
			background-color: var(--tile-toggle-selected-background, transparent);
		}
	}

	&.variantOutline {
		border-color: var(--tile-toggle-border, #{$border});
		box-shadow: var(--tile-toggle-shadow, #{$shadow-sm});
	}

	&.variantGhost {
		background-color: transparent;

		&[data-state='on'] {
			background-color: var(--tile-toggle-ghost-selected-background, #{$muted});
			color: var(--tile-toggle-ghost-selected-color, #{$muted-foreground});
		}
	}

	// 尺寸变体
	&.sizeDefault {
		height: var(--tile-toggle-height, 2.25rem);
		min-width: var(--tile-toggle-height, 2.25rem);
		padding: 0 var(--tile-toggle-padding-inline, #{$spacing-2});
	}

	&.sizeSm {
		height: var(--tile-toggle-sm-height, 2rem);
		min-width: var(--tile-toggle-sm-height, 2rem);
		padding: 0 var(--tile-toggle-sm-padding-inline, #{$spacing-1_5});
		font-size: var(--tile-toggle-sm-font-size, #{$text-sm});
		border-radius: var(--tile-toggle-sm-radius, #{$radius});
	}

	&.sizeLg {
		height: var(--tile-toggle-lg-height, 2.5rem);
		min-width: var(--tile-toggle-lg-height, 2.5rem);
		padding: 0 var(--tile-toggle-lg-padding-inline, #{$spacing-2_5});
	}
}
